// espera (s) antes de marcar cada mensagem como lida: a 1ª inclui 'abrir a conversa' (2-5 s)
const e = $('Montar entrada').first().json;
let ms = [];
try { ms = JSON.parse(e.mensagens || '[]'); } catch (err) {}
if (!ms.length) ms = [{ id: e.msgId, texto: e.texto_cliente || '' }];
const ale = (a, b) => a + Math.random() * (b - a);
const ler = (t) => {
  t = String(t || '');
  if (/^\[áudio\]/i.test(t)) return Math.min(25, Math.max(3, t.length / 14)) * ale(0.9, 1.1); // ouvir (~14 letras/s)
  if (/^\[foto/i.test(t)) return ale(2, 4);
  return Math.min(6, Math.max(0.8, t.length * 0.05)) * ale(0.8, 1.2); // ler (~20 letras/s)
};
return ms.filter((m) => m.id).map((m, i) => ({ json: { jid: e.jid, id: m.id,
  espera: Math.round(((i === 0 ? ale(2, 5) : ale(0.4, 1.2)) + ler(m.texto)) * 10) / 10 }, pairedItem: 0 }));

const jid = $('Montar entrada').first().json.jid;
// caractere invisível (espaço de largura zero) não é texto: em 27/10 a IA respondeu só isso e saiu um balão em branco
// conferente.js (ligado): a resposta que sai é a do Conferente (igual, reescrita ou versão segura); sem ele, a do agente
let t = ((() => { try { const c = $('Conferente: resposta').first().json; if (c && typeof c.texto === 'string') return c.texto; } catch (e) {} return $('Agente IA').first().json.output; })() || '').replace(/[\u200B-\u200D\u2060\uFEFF]/g, '').trim().replace(/\*\*([^*\n]+?)\*\*/g, '*$1*');
// ---- pix-sistema.js (1/2): a marca [[PIX: serviço; dia e hora]] da IA; o texto do Pix quem monta é o sistema ----
let pixPedido = null;
t = t.replace(/\[\[\s*PIX\b:?([^\]\n]*)\]\]|\[PIX(?::([^\]\n]*))?\]/g, (m, a, b) => { if (!pixPedido) pixPedido = { args: String(a || b || '') }; return '\n\n⟦PIX⟧\n\n'; }).trim();
// ---- fim pix-sistema.js (1/2) ----
// Prompt: se o áudio respondeu tudo, a IA não escreve nada. Áudio enviado + resposta vazia = não manda balão
// (sem isso cairia na mensagem de erro lá embaixo). [SEM TEXTO] também vale, se a IA usar.
const passos = $('Agente IA').first().json.intermediateSteps || [];
// fotos do catálogo enviadas também são resposta: se elas responderam tudo, a IA pode não escrever nada
const audioEnviado = passos.some(p => (p.action?.tool === 'enviar_audio' && /ÁUDIO ENVIADO/.test(JSON.stringify(p.observation || ''))) ||
  (p.action?.tool === 'enviar_catalogo' && /FOTOS ENVIADAS/.test(JSON.stringify(p.observation || ''))));
// Prompt v7.3: [[NAO_ENVIAR]] = a cliente só mandou um aceno (ok, assim) e a IA escolheu ficar quieta. Nunca vai pro WhatsApp
const semTexto = /\[SEM TEXTO\]|\[\[\s*NAO_ENVIAR\s*\]\]/i.test(t);
t = t.replace(/\[SEM TEXTO\]|\[\[\s*NAO_ENVIAR\s*\]\]/gi, '').trim();
// catálogo pedido e a IA não escreveu nada: sai só o link (catalogo-pdf.js)
const catalogoTexto = "Aqui está o catálogo do studio:\nhttps://wa.me/c/556696380737";
const catalogoPedido = passos.some(p => p.action?.tool === 'enviar_catalogo' && /FOTOS ENVIADAS/.test(JSON.stringify(p.observation || '')));
if (catalogoPedido && !t.replace(/\[\d{1,2}\]/g, '').replace(/[\s😊😉.!]/gu, '')) return [{ json: { jid, texto: catalogoTexto, falhou: false, citar: '', pausa: 1.5, delay: 2500 } }];
if ((audioEnviado || semTexto) && !t.replace(/\[\d{1,2}\]/g, '').replace(/[\s😊😉.!]/gu, '')) return [{ json: { jid, semTexto: true } }];
// --- numa linha = a IA quer outra mensagem a partir dali (ver COMO A RESPOSTA CHEGA NO WHATSAPP)
t = t.replace(/\n?[ \t]*-{3,}[ \t]*(\n|$)/g, '\n\n§§\n\n');
// Cumprimento (pedido do Victor, 26/10): devolve o MESMO que a cliente usou ('Boa tarde' às 17h59 → 'Boa tarde',
// não 'Boa noite' porque o relógio virou); se ela não cumprimentou, vale a hora do salão.
const hSalao = $now.setZone('America/Cuiaba').hour;
const dela = (String($('Montar entrada').first().json.texto_cliente || '').match(/bom dia|boa tarde|boa noite/gi) || []).pop();
const cumprimento = dela ? dela.toLowerCase() : hSalao < 12 ? 'bom dia' : hSalao < 18 ? 'boa tarde' : 'boa noite';
t = t.replace(/^(\s*(?:(?:oi|olá)[^.!?\n]{0,25}[!,.]\s*)?)(bom dia|boa tarde|boa noite)/i, (m, antes, g) => antes + (g[0] === g[0].toUpperCase() ? cumprimento[0].toUpperCase() + cumprimento.slice(1) : cumprimento));
// Cumprimenta UMA vez: se a IA já respondeu esta cliente nas últimas 3 h, tira o 'Oi, Victor! Boa tarde.' / 'Boa noite!' do
// começo (26/10: 'Boa tarde' e o áudio 30 s depois viraram duas respostas, cada uma com cumprimento)
const jaFalou = ($('Sobre esta cliente').first().json.texto || '').match(/Você já conversou com ela hoje \(sua última resposta foi às (\d\d):(\d\d)/);
const elaCumprimentou = /^\s*(\[\d+\]\s*)?(oi+e*|ol[áa]|opa|bom dia|boa tarde|boa noite)\b/i.test(String($('Montar entrada').first().json.texto_cliente || ''));
if (jaFalou && !elaCumprimentou) {
  const ultima = $now.setZone('America/Cuiaba').set({ hour: +jaFalou[1], minute: +jaFalou[2] });
  if ($now.diff(ultima, 'hours').hours < 3) {
    const semOi = t.replace(/^\s*(?:(?:oi|olá)(?:,\s*[^.!?\n]{1,25})?[!.,]\s*)?(?:(?:bom dia|boa tarde|boa noite)(?:,\s*[^.!?\n]{1,25})?[!.]\s*)?/i, '').trim();
    if (semOi) t = semOi[0].toUpperCase() + semOi.slice(1);
  }
}
// já conversaram hoje (ficha): tira a reapresentação que a IA às vezes ainda põe ('Sou a assistente virtual da Caroline.')
if (/Você já conversou com ela hoje/.test($('Sobre esta cliente').first().json.texto || '')) {
  const semApresentacao = t.replace(/(^|[.!?]\s+|\n)\s*((Eu )?sou a assistente virtual( da Caroline)?( Vieira)?|Aqui é a assistente( virtual)?( da Caroline)?)[^.!?\n]*[.!?]?/gi, '$1').trim();
  if (semApresentacao) t = semApresentacao;
}
// sem negrito/markdown: mensagem de gente não tem *asterisco*
t = t.replace(/\*\*(.+?)\*\*/g, '$1').replace(/\*([^*\n]+)\*/g, '$1').replace(/^#+\s*/gm, '').replace(/^\s*[-•]\s+/gm, '');
// frases de robô que a IA às vezes insiste em usar: tira antes de enviar (se sobrar texto)
const semRobo = t.replace(/\s*(como|em que) (posso|eu posso|poderia) (te |lhe )?ajudar( você)?( hoje)?\s*\?/gi, '').replace(/\s*(posso te ajudar|te ajudo) (em|com) (mais )?(algo|alguma coisa)( mais)?\s*\?/gi, '').replace(/, do Studio Caroline Ferreira/gi, '').trim();
if (semRobo) t = semRobo;
// sobras de chatbot no fim (humanizer §22): fecho automático que não diz nada; só sai se sobrar texto
// "Qualquer dúvida, estou à disposição." sai inteira: a frase do "qualquer dúvida" vem antes da do "disposição" (senão sobrava "Qualquer dúvida,.")
// só quando o fecho é a frase inteira: no meio da frase ("Quando decidir ou se precisar, é só me chamar") cortava e sobrava "Quando decidir ou." (10/11)
const semFecho = t.replace(/(^|[.!?\n])\s*(qualquer coisa|qualquer d[úu]vida|se precisar|se tiver (alguma|mais alguma) d[úu]vida)[^.!?\n]*(estou|estamos|é só|me (chama|fala|avisa))[^.!?\n]*[.!?]?/gi, '$1').replace(/\s*(fico|ficamos|estou|estamos) (à|a) (sua )?disposi[çc][ãa]o[^.!?\n]*[.!?]?/gi, '').replace(/\s*espero ter ajudado[.!]?/gi, '').replace(/\s*(e )?estou aqui (pra|para) (te |lhe )?ajudar[.!]?/gi, '').replace(/[\s,;:]+$/, '').trim();
if (semFecho && semFecho !== t) t = /[.!?😊😉]$/u.test(semFecho) ? semFecho : semFecho + '.';
// palavra de controle das ferramentas ("REMARCADO! Mudei…"): é para a IA, não para a cliente
t = t.replace(/\b(REMARCADO|AGENDADO|CANCELADO|ANOTADO)\b[!.:,]?\s*/g, '').replace(/^\s*([a-zà-ú])/, (m, l) => m.replace(l, l.toUpperCase()));
// regra da Caroline: valor de serviço só quando a cliente pergunta preço (prompt v5). Se ela não perguntou, tira
// as frases com valor ou 'o valor depende…' (a IA às vezes solta mesmo assim) e o 'que legal' de robô
// "e a selagem?" logo depois de um preço também é pergunta de preço (a IA só fala valor se fizer sentido)
const msgCliente = $('Montar entrada').first().json.texto_cliente || '';
// "só queria saber o total", "me dá uma base", "dá pra parcelar?" também são pergunta de preço (10/11: a resposta saía sem o valor)
let precoPendente = false;
try { precoPendente = String($('Preço: ler pendência').first().json.pendente || '') === '1'; } catch (e) {}
const pediuPrecoAgora = /(quanto|valor|pre[cç]o|cust|or[cç]amento|caro|barat|cobra|tabela|\btotal\b|uma base|uma ideia|uma no[cç][ãa]o|m[ée]dia|pagar|pagamento|parcel|investimento)/i.test(msgCliente) || /^\s*e (a|o|as|os|pra|para|no|na)\b[^?]{0,40}\?\s*$/i.test(msgCliente);
const pediuPreco = true; // loja com preco_livre
const FRASES = /(?<=[.!?😊😉🥰])\s+/u;
const QUANDO = /\b\d{1,2}(h|:\d\d)/;
// valor em dinheiro: R$ 160, R$160,00 ou 350 reais
const PRECO_MANUT = /a partir de R\$\s?150(?:,00)?\s+por tela/i;
const ofertaManut = /manuten[cç][aã]o/i.test(t) && QUANDO.test(t) && PRECO_MANUT.test(t) && (t.match(/R\$\s?\d/g) || []).length === 1;
const VALOR = /R\$\s?\d|\b\d{2,}(?:\.\d{3})*(?:,\d{2})?\s*reais\b/i;
// limpa linha por linha: o quadro da agenda vem uma linha por período e precisa chegar assim
const limpar = (p) => p.split('\n').map(limparLinha).filter(Boolean).join('\n');
const limparLinha = (p) => {
  let fs = p.split(FRASES).filter(f => !/^(ah,? )?que legal\b/i.test(f));
  // frase que também oferece horário ("que fica R$ 450, eu tenho segunda às 13h"): tira só o preço, senão a
  // cliente recebe "algum desses horários?" sem horário nenhum
  if (!pediuPreco) fs = fs.map(f => {
    // exceção (13/11, Adriana): ao oferecer horário de manutenção a IA diz 'a partir de R$ 150 por tela' sem a cliente
    // pedir, para ela não descobrir o valor depois de marcada. Só passa essa frase, e só se for o único valor do texto
    // o sinal de R$ 20 de quem faltou (13/11) faz parte do combinado do horário: a frase com a palavra 'sinal' passa
    if (!VALOR.test(f) || (ofertaManut && PRECO_MANUT.test(f)) || /\bsinal\b[^.!?]*R\$\s?20\b|R\$\s?20\b[^.!?]*\bsinal\b/i.test(f)) return f;
    const s = f.replace(/,?\s*(?:que\s+)?(?:fica|custa|sai|é|está|no valor de|por)?\s*(?:em\s+|por\s+|de\s+)?(?:a partir de\s+)?(?:R\$\s?\d+(?:\.\d{3})*(?:,\d{2})?(?:\s*reais)?|\d{2,}(?:\.\d{3})*(?:,\d{2})?\s*reais)/gi, '').replace(/\s+,/g, ',').replace(/^[\s,;:–-]+/, '').trim().replace(/^\p{Ll}/u, (l) => l.toUpperCase());
    return !VALOR.test(s) && !/R\$/.test(s) && QUANDO.test(s) ? s : '';
  }).filter(Boolean);
  if (!pediuPreco && !ofertaManut) fs = fs.filter(f => !/\bvalor\b[^.?!]*\bdepende/i.test(f));
  return fs.join(' ').trim();
};
// [n] = parágrafo que responde a n-ª mensagem seguida dela. Número no meio do texto também abre parágrafo;
// parágrafo sem número continua respondendo a mesma mensagem do anterior
t = t.replace(/\s*\[(\d{1,2})\]\s*/g, '\n\n[$1] ').trim();
let ref = 0;
let paragrafos = t.split(/\n\s*\n/).map(s => { const m = s.trim().match(/^\[(\d{1,2})\]\s*/); if (m) ref = Number(m[1]); return { t: s.trim().slice(m ? m[0].length : 0).trim(), ref }; }).filter(p => p.t);
const limpos = paragrafos.map(p => ({ t: limpar(p.t), ref: p.ref })).filter(p => p.t);
// só sobra §§ (marca do ---) = a limpeza tirou todo o texto: fica a resposta como veio
if (limpos.some(p => p.t !== '§§')) paragrafos = limpos;
// Rede de segurança: se a IA falhar e devolver vazio, a cliente não fica sem resposta
const falhou = !paragrafos.some(p => p.t !== '§§'); // o alerta-workflows.js avisa o Victor
if (falhou) paragrafos = [{ t: 'Desculpa, tive um probleminha aqui e não consegui ler sua mensagem. Pode mandar de novo? 😊', ref: 0 }];
// Como gente manda no WhatsApp (pedido do Victor, 26/10): um balão por parágrafo, na ordem, no máximo 2.
// Parágrafo minúsculo (menos de 25 letras, ex.: 'Oi, Maria!') gruda no seguinte; parágrafo enorme (mais de
// 300 letras) é cortado entre frases; se passar de 3, os do fim se juntam no 3º. O --- da IA conta como parágrafo.
const ps = paragrafos.filter(p => p.t !== '§§').map(p => p.t);
let baloes = [];
let junto = '';
for (const p of ps) {
  junto = junto ? junto + '\n\n' + p : p;
  if (junto.length >= 25) { baloes.push({ t: junto, ref: 0 }); junto = ''; }
}
if (junto) { if (baloes.length) baloes[baloes.length - 1].t += '\n\n' + junto; else baloes.push({ t: junto, ref: 0 }); }
const cortar = (t) => {
  if (t.length <= 300 || t.includes('\n')) return [t]; // quadro do dia (em linhas) vai inteiro
  const fs = t.split(FRASES);
  if (fs.length < 2) return [t];
  let a = '', i = 0;
  while (i < fs.length - 1 && (a + ' ' + fs[i]).trim().length < t.length / 2) a = (a + ' ' + fs[i++]).trim();
  if (!a) a = fs[i++];
  return [a, fs.slice(i).join(' ').trim()].filter(Boolean);
};
baloes = baloes.flatMap((b) => cortar(b.t).map((t) => ({ t, ref: 0 })));
// no máximo 2 balões (26/10: 3 balões era texto demais)
if (baloes.length > 2) baloes = [baloes[0], { t: baloes.slice(1).map(b => b.t).join('\n\n'), ref: 0 }];
baloes = baloes.filter(b => b.t);
// ---- saida-limpa.js ----
try {
  const sp = ((($('Supabase: dados do salão').first().json.config || {}).loja || {}).sinal_pix) || {};
  const chave = String(sp.chave || '').trim();
  const nomes = [].concat(sp.nome_recebedor || []).map((n) => String(n || '').trim()).filter(Boolean).sort((a, b) => b.length - a.length);
  const escapar = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  // 2. "reservei" antes do sinal: só quando esta resposta pede o sinal e nenhum horário foi gravado agora
  const passosIA = $('Agente IA').first().json.intermediateSteps || [];
  const gravouAgora = passosIA.some((p) => ['criar_agendamento', 'remarcar_agendamento'].includes(p.action?.tool) && /AGENDADO|REMARCADO/.test(JSON.stringify(p.observation || '')));
  const pedeSinal = baloes.some((b) => (chave && b.t.includes(chave)) || /(é só|basta|precis[ao] d[eo]|preciso de)\s+(um |o )?sinal|sinal\s+(de\s+)?R\$\s?\d+[^.!?]*\bagora\b|mand[ae]r?\s+(o\s+|um\s+)?(print|comprovante)/i.test(b.t));
  if (pedeSinal && !gravouAgora) {
    baloes.forEach((b) => {
      b.t = b.t.replace(/\b(j[áa]\s+)?(reservei|deixei\s+reservad[oa])(\s+(ele|esse\s+hor[áa]rio|seu\s+hor[áa]rio))?(\s+aqui)?(\s+(pra|para)\s+(voc[eê]|ti))?(?=[\s!.,;]|$)/gi, 'esse horário está livre pra você');
    });
  }
  // 3. palavra solta em inglês que sobra do modelo
  baloes.forEach((b) => { b.t = b.t.replace(/\s*\bturn[- ]?off\b/gi, '').replace(/\s+([.!?,])/g, '$1').trim(); });
  // 1. chave Pix num balão só dela
  if (chave) {
    const novos = [];
    for (const b of baloes) {
      if (!b.t.includes(chave) || b.t.trim() === chave) { novos.push(b); continue; }
      const i = b.t.indexOf(chave);
      let antes = b.t.slice(0, i), depois = b.t.slice(i + chave.length);
      let nomeJunto = '';
      for (const n of nomes) {
        const re = new RegExp('^[\\s/:–-]*' + escapar(n) + '[\\s.]*', 'i');
        if (re.test(depois)) { depois = depois.replace(re, ' '); nomeJunto = n; break; }
      }
      // tira "chave:" / "Pix:" pendurado no fim do texto de antes (a chave vem logo depois, sozinha)
      antes = antes.replace(/[\s/:–-]+$/, '').trim();
      depois = depois.replace(/^[\s/:–-]+/, '').trim();
      if (nomeJunto && !antes.toLowerCase().includes(nomeJunto.toLowerCase())) antes = (antes ? antes + (/[.!?]$/.test(antes) ? ' ' : '. ') : '') + 'Pix em nome de ' + nomeJunto + ':';
      if (antes) novos.push({ t: antes, ref: 0 });
      novos.push({ t: chave, ref: 0 });
      if (depois) novos.push({ t: depois, ref: 0 });
    }
    baloes = novos;
  }
  baloes = baloes.filter((b) => b.t);
} catch (e) {}
// ---- fim saida-limpa.js ----
// ---- pix-sistema.js (2/2) ----
{
  const MARCA = '⟦PIX⟧';
  const tirarMarca = () => { baloes = baloes.map((b) => ({ ...b, t: b.t.split(MARCA).join(' ').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').replace(/[ \t]{2,}/g, ' ').trim() })).filter((b) => b.t); };
  let chaveReserva = '';
  try {
    const sp = ((($('Supabase: dados do salão').first().json.config || {}).loja || {}).sinal_pix) || {};
    const chave = String(sp.chave || '').trim();
    chaveReserva = chave;
    const valor = Number(sp.valor || 0);
    const ligado = !!sp.ativo && !!chave && valor > 0;
    const semEsp = (s) => String(s || '').replace(/\s+/g, '');
    const esc = (s) => s.replace(/[.*+?^$()|[\]\\{}]/g, '\\$&');
    const reChave = new RegExp(semEsp(chave).split('').map(esc).join('\\s*') || '(?!)', 'g');
    const temChave = (s) => !!chave && semEsp(s).includes(semEsp(chave));
    const temMarca = baloes.some((b) => b.t.includes(MARCA));
    const chaveSolta = ligado && !temMarca && baloes.some((b) => temChave(b.t));
    if (!ligado || (!temMarca && !chaveSolta)) { if (temMarca) tirarMarca(); }
    else {
      const pega = (no, f, padrao) => { try { return f($(no)); } catch (e) { return padrao; } };
      const norm = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
      const servicos = pega('Supabase: tabela de serviços', (n) => n.all().map((i) => i.json).filter((s) => s && s.nome), []);
      const recentes = pega('Supabase: últimas mensagens', (n) => n.all().map((i) => i.json).filter((m) => m && m.direcao && m.criado_em), []);
      const ficha = String(pega('Sobre esta cliente', (n) => n.first().json.texto, '') || '');
      const msgDela = String(pega('Montar entrada', (n) => n.first().json.texto_cliente, '') || '');
      const passosPix = pega('Agente IA', (n) => n.first().json.intermediateSteps, []) || [];
      const agoraMs = Date.now();
      const horas = Math.max(0, Number(sp.chave_repetir_horas) || 12);
      const dentro = (m) => agoraMs - Date.parse(m.criado_em) <= horas * 3600e3;
      // a chave já saiu (pela IA, pela assistente ou pela dona) nas últimas horas?
      const ultimaChave = Math.max(0, ...recentes.filter((m) => m.direcao === 'saida' && dentro(m) && temChave(m.conteudo)).map((m) => Date.parse(m.criado_em)));
      const pagouDepois = recentes.some((m) => m.direcao === 'entrada' && dentro(m) && /COMPROVANTE PIX/i.test(String(m.conteudo || '')) && Date.parse(m.criado_em) > ultimaChave);
      // ela pediu a chave de novo ("não achei a chave", "manda o pix de novo", "qual a chave?")
      const pediuChave = /\b(chave|pix)\b/i.test(msgDela) && /(de novo|novamente|outra vez|n[ãa]o (achei|encontrei|veio|chegou|apareceu|consigo|consegui|t[ôo] achando)|reenvi|manda(r|)\s+(a|o|de novo|aqui|a[ií])\b|qual (é |e )?(a|o)\b|me passa|passa (a|o|de novo)|copiar)/i.test(msgDela);
      const gravouAgora = passosPix.some((p) => p && p.action && ['criar_agendamento', 'remarcar_agendamento'].includes(p.action.tool) &&
        /\b(AGENDADO|REMARCADO)\b/.test(String(typeof p.observation === 'string' ? p.observation : JSON.stringify(p.observation || ''))) &&
        !/N[ÃA]O (AGENDADO|REMARCADO)/.test(String(typeof p.observation === 'string' ? p.observation : JSON.stringify(p.observation || ''))));
